<?php require 'config/database.php';require 'includes/auth.php';require_role('admin');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$stock=max(0,(int)$_POST['stock']);$pdo->prepare("UPDATE rewards SET stock=? WHERE id=?")->execute([$stock,$id]);$msg='Inventory updated.';}$items=$pdo->query("SELECT * FROM rewards ORDER BY points_required")->fetchAll();$pageTitle='Rewards inventory';include 'includes/header.php';?><div class="page-heading"><span class="eyebrow">ADMINISTRATION</span><h1>Rewards and inventory</h1><p>Update available stock for academic supplies.</p></div><?php if($msg):?><div class="notice success"><?=$msg?></div><?php endif;?><div class="reward-grid"><?php foreach($items as $it):?><div class="panel inventory-card"><h3><?=htmlspecialchars($it['name'])?></h3><p><?=$it['points_required']?> points required</p><form method="post"><input type="hidden" name="id" value="<?=$it['id']?>"><label>Available stock<input type="number" min="0" name="stock" value="<?=$it['stock']?>"></label><button class="btn primary small">Save stock</button></form></div><?php endforeach;?></div><?php include 'includes/footer.php';?>
